import { createContext, useContext, useEffect, useState } from 'react';
import { supabase } from '@/lib/supabase';
import { useAuth } from './AuthContext';

const RealtimeContext = createContext(null);

export function RealtimeProvider({ children }) {
  const { user } = useAuth();
  const [tasks, setTasks] = useState([]);
  const [shoppingItems, setShoppingItems] = useState([]);
  const [events, setEvents] = useState([]);

  useEffect(() => {
    if (!user?.householdId) return;

    const tasksChannel = supabase
      .channel(`tasks-${user.householdId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'tasks',
        filter: `household_id=eq.${user.householdId}`
      }, loadTasks)
      .subscribe();

    const shopChannel = supabase
      .channel(`shop-${user.householdId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'shopping_items',
        filter: `household_id=eq.${user.householdId}`
      }, loadShop)
      .subscribe();

    const eventsChannel = supabase
      .channel(`events-${user.householdId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'household_events',
        filter: `household_id=eq.${user.householdId}`
      }, loadEvents)
      .subscribe();

    loadTasks();
    loadShop();
    loadEvents();

    return () => {
      supabase.removeChannel(tasksChannel);
      supabase.removeChannel(shopChannel);
      supabase.removeChannel(eventsChannel);
    };
  }, [user?.householdId]);

  const loadTasks = async () => {
    const { data } = await supabase.from('tasks').select('*').eq('household_id', user?.householdId);
    if (data) setTasks(data);
  };

  const loadShop = async () => {
    const { data } = await supabase.from('shopping_items').select('*').eq('household_id', user?.householdId);
    if (data) setShoppingItems(data);
  };

  const loadEvents = async () => {
    const { data } = await supabase.from('household_events').select('*').eq('household_id', user?.householdId);
    if (data) setEvents(data);
  };

  return <RealtimeContext.Provider value={{ tasks, shoppingItems, events }}>{children}</RealtimeContext.Provider>;
}

export const useRealtime = () => useContext(RealtimeContext);

